# HỢP ĐỒNG + SOẠN WORD
# =========================================================
# TẠO HỢP ĐỒNG WORD MỚI
# =========================================================
def number_to_vietnamese(n):
    n=int(round(float(n or 0)))
    if n==0: return "Không đồng"
    d=["không","một","hai","ba","bốn","năm","sáu","bảy","tám","chín"]
    def r3(x, full=False):
        a,b,c=x//100,(x//10)%10,x%10; s=[]
        if a or full: s += [d[a],"trăm"]
        if b==0 and c and (a or full): s += ["lẻ"]
        elif b: s += [d[b],"mươi"]
        if c:
            if b>=2 and c==1: w="mốt"
            elif b>=1 and c==5: w="lăm"
            elif b>=2 and c==4: w="tư"
            else: w=d[c]
            s.append(w)
        return " ".join(s)
    units=["","nghìn","triệu","tỷ"]; groups=[]
    while n: groups.append(n%1000); n//=1000
    out=[]
    for i in range(len(groups)-1,-1,-1):
        if groups[i]: out += [r3(groups[i], i==len(groups)-1), units[i]] if i else [r3(groups[i], True)]
    return " ".join(out).capitalize()+" đồng"


# =========================================================
# SOẠN HỢP ĐỒNG: DÙNG CHÍNH FILE MẪU, CHỈ ĐIỀN Ô TRỐNG
# =========================================================
import base64
import gzip
import io
import tempfile

_BOOKING_TEMPLATE_B64 = ""
_CTV_TEMPLATE_B64 = ""

def _load_template(b64_text):
    return io.BytesIO(gzip.decompress(base64.b64decode(b64_text)))

def _replace_runs(run_list, replacements):
    """Thay text ngay trong run để giữ nguyên font/bold/format của mẫu."""
    for run in run_list:
        for old, new in replacements:
            if old in run.text:
                run.text = run.text.replace(old, str(new))

def _replace_paragraph(doc, idx, replacements):
    if 0 <= idx < len(doc.paragraphs):
        p = doc.paragraphs[idx]
        # Thay từ phải sang trái theo thứ tự xuất hiện để các dấu … lặp lại
        # không bị biến thành cùng một giá trị (đặc biệt ngày/tháng/năm).
        runs = p.runs
        for old_text, new_text in replacements:
            target = str(old_text)
            replacement = str(new_text)
            for run in runs:
                if target and target in run.text:
                    run.text = run.text.replace(target, replacement)

def _set_paragraph_left(doc, idx):
    if 0 <= idx < len(doc.paragraphs):
        from docx.enum.text import WD_ALIGN_PARAGRAPH
        doc.paragraphs[idx].alignment = WD_ALIGN_PARAGRAPH.LEFT

def _replace_cell(cell, replacements):
    for p in cell.paragraphs:
        _replace_runs(p.runs, replacements)

def _fill_blank_cell_preserve_format(cell, text, reference_cell=None):
    """Điền vào ô đang trống mà không phá format của mẫu Word."""
    text = str(text or "")
    if not text:
        return
    # Nếu ô có placeholder thì dùng cơ chế thay thế hiện tại.
    if cell.text.strip():
        _replace_cell(cell, [("…", text), ("...", text), ("....", text), ("…..", text)])
        if text in cell.text:
            return

    # Ô hoàn toàn trống: tạo run và copy format từ ô tham chiếu.
    p = cell.paragraphs[0] if cell.paragraphs else cell.add_paragraph()
    run = p.add_run(text)
    if reference_cell is not None:
        ref_runs = [
            r for p0 in reference_cell.paragraphs for r in p0.runs
        ]
        if ref_runs:
            run._r.get_or_add_rPr().clear_content()
            if ref_runs[0]._r.rPr is not None:
                run._r.get_or_add_rPr().append(copy(ref_runs[0]._r.rPr))

def _replace_all_in_doc(doc, replacements):
    for p in doc.paragraphs:
        _replace_runs(p.runs, replacements)
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                _replace_cell(cell, replacements)

def make_booking_doc(data, path):
    try:
        from docx import Document
    except ModuleNotFoundError:
        raise RuntimeError("Thiếu thư viện python-docx. Hãy thêm python-docx vào requirements.txt rồi redeploy Streamlit.")

    doc = Document(_load_template(_BOOKING_TEMPLATE_B64))

    # Header + thông tin hai bên
    # Mẫu gốc đang để các dòng thông tin bên A/B ở chế độ Justify;
    # khi điền tên mới Word kéo giãn khoảng trắng giữa từng từ. Chỉ
    # chuyển các dòng thông tin này sang căn trái, không thay đổi font.
    for _idx in [12, 14, 15, 16, 17, 18, 19]:
        _set_paragraph_left(doc, _idx)

    _replace_paragraph(doc, 4, [("…-", f"{data['number']}-")])
    _replace_paragraph(doc, 10, [
        (
            "Hôm nay, ngày … tháng … năm ….,",
            f"Hôm nay, ngày {data['day']:02d} tháng {data['month']:02d} năm {data['year']},"
        )
    ])
    _replace_paragraph(doc, 14, [("….", data["partner"])])
    _replace_paragraph(doc, 15, [("…..", data["rep"])])
    _replace_paragraph(doc, 16, [(" ….", f" {data['position']}")])
    _replace_paragraph(doc, 17, [(": …..", f": {data['address']}")])
    _replace_paragraph(doc, 18, [(" ….", f" {data['phone']}")])
    _replace_paragraph(doc, 19, [("…..", data["tax"])])

    # Nội dung gói
    _replace_paragraph(doc, 23, [
        ("… gói …", f"{data['qty']} gói {data['package']}")
    ])
    _replace_paragraph(doc, 27, [("….", data["package"])])
    _replace_paragraph(doc, 28, [("…", data["qty"])])
    _replace_paragraph(doc, 30, [("…", data["free"])])
    _replace_paragraph(doc, 31, [("…", data["micro"])])
    _replace_paragraph(doc, 32, [("…", data["macro"])])
    _replace_paragraph(doc, 33, [("…", data["commission"])])
    _replace_paragraph(doc, 34, [("…", data["ads"])])

    # 3 dòng sản phẩm + 3 dòng tiêu chí của chính mẫu.
    for idx, value in zip([38, 39, 40], data.get("products", ["", "", ""])):
        _replace_paragraph(doc, idx, [("…", value)])
    for idx, value in zip([42, 43, 44], data.get("criteria_lines", ["", "", ""])):
        _replace_paragraph(doc, idx, [("…", value)])

    # Giá trị hợp đồng.
    _replace_paragraph(doc, 71, [("….", data.get("amount_words") or number_to_vietnamese(data["total"]))])
    _replace_paragraph(doc, 73, [("…. VNĐ", f"{data['total']:,.0f} VNĐ")])

    # Bảng tiền trong chính template.
    table = doc.tables[0]
    _replace_cell(table.cell(1, 3), [("….", f"{data['fee']:,.0f}")])
    _replace_cell(table.cell(1, 4), [("….", f"{data['fee']:,.0f}")])
    _replace_cell(table.cell(2, 3), [("….", f"{data['vat']:,.0f}")])
    _replace_cell(table.cell(2, 4), [("….", f"{data['vat']:,.0f}")])
    _replace_cell(table.cell(3, 3), [("….", f"{data['total']:,.0f}")])
    _replace_cell(table.cell(3, 4), [("….", f"{data['total']:,.0f}")])

    doc.save(path)

def make_ctv_doc(data, path):
    try:
        from docx import Document
    except ModuleNotFoundError:
        raise RuntimeError("Thiếu thư viện python-docx. Hãy thêm python-docx vào requirements.txt rồi redeploy Streamlit.")

    doc = Document(_load_template(_CTV_TEMPLATE_B64))

    # Số hợp đồng + ngày ký + nhãn hàng.
    _replace_paragraph(doc, 5, [("…/", f"{data['number']}/")])
    _replace_paragraph(doc, 9, [
        ("21 tháng 09 năm 2026",
         f"{data['day']:02d} tháng {data['month']:02d} năm {data['year']}")
    ])
    _replace_paragraph(doc, 26, [("…", data["brand"])])

    # Thông tin CTV trong bảng của mẫu.
    t_info = doc.tables[1]
    _replace_cell(t_info.cell(0, 2), [("….", data["name"])])
    _replace_cell(t_info.cell(1, 2), [("….", data["dob"])])
    _replace_cell(t_info.cell(2, 2), [
        ("…  - Ngày cấp: ….  - Nơi cấp:",
         f"{data['cccd']} - Ngày cấp: {data['cccd_date']} - Nơi cấp:")
    ])
    _replace_cell(t_info.cell(3, 2), [("…", data["tax"])])
    _replace_cell(t_info.cell(4, 2), [
        ("…- Ngân hàng: Ngân hàng ….",
         f"{data['account']}- Ngân hàng: Ngân hàng {data['bank']}")
    ])

    # Bảng công việc/đơn giá/thành tiền.
    t_work = doc.tables[2]
    _fill_blank_cell_preserve_format(
        t_work.cell(1, 1),
        data.get("username", ""),
        reference_cell=t_work.cell(1, 2)
    )
    _replace_cell(t_work.cell(1, 3), [("…", data["qty"])])
    _replace_cell(t_work.cell(1, 4), [(" …", f" {data.get('unit_price', data.get('gross', 0) / data.get('qty', 1) if data.get('qty', 0) else 0):,.0f}")])
    _replace_cell(t_work.cell(1, 5), [("….", f"{data['gross']:,.0f}")])
    _replace_cell(t_work.cell(2, 5), [("…", f"{data['gross']:,.0f}")])

    # Bảng tổng tiền.
    t_money = doc.tables[3]
    _replace_cell(t_money.cell(0, 2), [("….", f"{data['gross']:,.0f}")])
    _replace_cell(t_money.cell(1, 2), [("… ", f"{data['tax']:,.0f} ")])
    _replace_cell(t_money.cell(2, 2), [("…..", f"{data['net']:,.0f}")])

    # Bằng chữ + điều khoản thanh toán: dùng số thực nhận như mẫu CTV.
    _replace_paragraph(doc, 32, [("…", number_to_vietnamese(data["net"]))])
    _replace_paragraph(doc, 35, [
        ("…. VNĐ", f"{data['net']:,.0f} VNĐ"),
        ("….", number_to_vietnamese(data["net"]))
    ])

    doc.save(path)

