# =========================================================
# LIVE TAP GOOGLE SHEET
# =========================================================
TAP_GSHEET_DEFAULT_URL = "https://docs.google.com/spreadsheets/d/1PQ1xMvmE1vvuJsndnlbasULpB5YXg7ViC8kqm3AgPcg/edit?gid=804857795#gid=804857795"
TAP_GSHEET_DEFAULT_GID = "804857795"


def parse_google_sheet_url(sheet_url):
    """Lấy Spreadsheet ID + GID từ link Google Sheet người dùng dán vào."""
    sheet_url = (sheet_url or "").strip()
    if not sheet_url:
        return None, None, "Chưa nhập link Google Sheet."

    match = re.search(r"/spreadsheets/d/([a-zA-Z0-9-_]+)", sheet_url)
    if not match:
        return None, None, "Link không đúng định dạng Google Sheet."

    spreadsheet_id = match.group(1)
    parsed = urllib.parse.urlparse(sheet_url)
    params = urllib.parse.parse_qs(parsed.query)
    gid = params.get("gid", [None])[0]

    # Hỗ trợ cả trường hợp link có #gid=...
    if not gid and parsed.fragment:
        frag_match = re.search(r"(?:^|&)gid=([0-9]+)", parsed.fragment)
        if frag_match:
            gid = frag_match.group(1)

    # Nếu người dùng chỉ dán link /edit thì dùng tab Tiến Độ TAP mặc định.
    if not gid:
        gid = TAP_GSHEET_DEFAULT_GID

    return spreadsheet_id, gid, None


@st.cache_data(ttl=300, show_spinner=False)
def load_tap_gsheet(sheet_url):
    spreadsheet_id, gid, parse_err = parse_google_sheet_url(sheet_url)
    if parse_err:
        return pd.DataFrame(), parse_err

    # Ưu tiên Google Visualization (gviz) vì một số Google Workspace
    # trả HTTP 401 với endpoint /export dù Sheet đã bật "Anyone with the link".
    urls = [
        (
            f"https://docs.google.com/spreadsheets/d/{spreadsheet_id}"
            f"/gviz/tq?tqx=out:csv&gid={gid}"
        ),
        (
            f"https://docs.google.com/spreadsheets/d/{spreadsheet_id}"
            f"/export?format=csv&gid={gid}"
        ),
    ]

    errors = []
    for csv_url in urls:
        try:
            import requests
            response = requests.get(
                csv_url,
                timeout=25,
                headers={"User-Agent": "Mozilla/5.0"},
                allow_redirects=True,
            )
            response.raise_for_status()

            # Google có thể trả HTML trang đăng nhập thay vì CSV.
            content_type = response.headers.get("Content-Type", "").lower()
            text = response.content.decode("utf-8-sig", errors="replace")
            if "text/html" in content_type and "google.visualization" not in text:
                raise RuntimeError(f"Google trả về HTML thay vì dữ liệu CSV (HTTP {response.status_code}).")

            from io import StringIO
            df = pd.read_csv(StringIO(text))
            df = df.dropna(how="all")
            df.columns = [str(c).strip() for c in df.columns]
            if not df.empty or len(df.columns) > 0:
                return df, None
            errors.append("Google trả về CSV rỗng.")
        except Exception as e:
            errors.append(f"{type(e).__name__}: {e}")

    return pd.DataFrame(), " | ".join(errors)


def render_live_tap():
    st.header("Phân tích TAP")
    st.caption("🔗 Kết nối dữ liệu trực tiếp từ Google Sheet — Tiến Độ TAP")

    if "tap_gsheet_url" not in st.session_state:
        st.session_state.tap_gsheet_url = TAP_GSHEET_DEFAULT_URL

    sheet_url = st.text_input(
        "🔗 Link Google Sheet",
        value=st.session_state.tap_gsheet_url,
        placeholder="Dán link Google Sheet vào đây...",
        key="tap_gsheet_url_input",
        help="Dán link Google Sheet bình thường. Link có ?gid=... sẽ tự xác định đúng tab.",
    )
    st.session_state.tap_gsheet_url = sheet_url.strip()

    c1, c2 = st.columns([1, 5])
    with c1:
        if st.button("🔄 Kết nối / Cập nhật", use_container_width=True, key="refresh_live_tap"):
            load_tap_gsheet.clear()
            st.rerun()
    with c2:
        st.caption("App tự lấy dữ liệu mới tối đa mỗi 5 phút. Bấm Cập nhật để lấy số mới ngay.")

    if not sheet_url.strip():
        st.info("👆 Dán link Google Sheet vào ô phía trên để kết nối dữ liệu.")
        return

    df, err = load_tap_gsheet(sheet_url.strip())
    if err:
        st.error("❌ Không đọc được Google Sheet.")
        st.caption(f"Chi tiết: {err}")
        st.info(
            "Hãy kiểm tra: Google Sheet → Chia sẻ → Quyền truy cập chung → "
            "Bất kỳ ai có đường liên kết → Người xem."
        )
        return
    if df.empty:
        st.warning("Google Sheet không có dữ liệu.")
        return

    def _norm_col(value):
        # Chuẩn hóa tên cột: xuống dòng, dấu ngoặc [tổng], dấu tiếng Việt...
        text = str(value).replace("\n", " ").replace("\r", " ")
        text = re.sub(r"\[[^\]]*\]", " ", text)
        text = text.strip().lower()
        text = unicodedata.normalize("NFD", text)
        text = "".join(ch for ch in text if unicodedata.category(ch) != "Mn")
        text = text.replace("đ", "d")
        text = re.sub(r"[^a-z0-9/]+", " ", text)
        return re.sub(r"\s+", " ", text).strip()

    def col(*names):
        normalized = [(str(x), _norm_col(x)) for x in df.columns]
        wanted = [_norm_col(name) for name in names]
        for want in wanted:
            for original, norm in normalized:
                if norm == want:
                    return original
        for want in wanted:
            for original, norm in normalized:
                if want and (norm.startswith(want) or want in norm):
                    return original
        return None

    brand = col("TAP", "TAP / Brand", "Brand")
    pic = col("PIC")
    status = col("Trạng thái", "Status")
    target = col("Mục tiêu video")
    video = col("Video")
    kol = col("KOL đang hợp tác")
    pick = col("Brand pick")
    sample = col("Đã gửi Sample", "Đã gửi\nSample")
    posted = col("Đã đăng bài")

    a, b, c = st.columns(3)
    with a:
        pics = ["Tất cả"] + (sorted(df[pic].astype(str).replace("nan", "").unique().tolist()) if pic else [])
        sel_pic = st.selectbox("PIC", pics, key="live_tap_pic")
    with b:
        brands = ["Tất cả"] + (sorted(df[brand].astype(str).replace("nan", "").unique().tolist()) if brand else [])
        sel_brand = st.selectbox("Brand / TAP", brands, key="live_tap_brand")
    with c:
        statuses = ["Tất cả"] + (sorted(df[status].astype(str).replace("nan", "").unique().tolist()) if status else [])
        sel_status = st.selectbox("Trạng thái", statuses, key="live_tap_status")

    fdf = df.copy()
    if pic and sel_pic != "Tất cả":
        fdf = fdf[fdf[pic].astype(str) == sel_pic]
    if brand and sel_brand != "Tất cả":
        fdf = fdf[fdf[brand].astype(str) == sel_brand]
    if status and sel_status != "Tất cả":
        fdf = fdf[fdf[status].astype(str) == sel_status]

    def num(col_name):
        if not col_name or col_name not in fdf.columns:
            return 0.0
        return pd.to_numeric(
            fdf[col_name].astype(str).str.replace(",", "", regex=False).str.replace("%", "", regex=False),
            errors="coerce"
        ).fillna(0).sum()

    brand_count = fdf[brand].replace("", pd.NA).nunique() if brand else len(fdf)
    total_target = num(target)
    total_video = num(video)
    total_kol = num(kol)
    total_pick = num(pick)
    total_sample = num(sample)
    total_posted = num(posted)

    a, b, c, d = st.columns(4)
    a.metric("Brand", f"{brand_count:,.0f}")
    b.metric("Mục tiêu video", f"{total_target:,.0f}")
    c.metric("Video", f"{total_video:,.0f}")
    d.metric("KOL đang hợp tác", f"{total_kol:,.0f}")

    a, b, c = st.columns(3)
    a.metric("Brand pick", f"{total_pick:,.0f}")
    b.metric("Đã gửi Sample", f"{total_sample:,.0f}")
    c.metric("Đã đăng bài", f"{total_posted:,.0f}")

    if total_target > 0:
        progress = min(total_video / total_target, 1.0)
        st.write(f"**Tiến độ Video:** {total_video:,.0f} / {total_target:,.0f} ({total_video / total_target:.1%})")
        st.progress(progress)

    st.dataframe(fdf, use_container_width=True, hide_index=True)


